<?php
$choices=query('SELECT c.id,c.crop,c.season,l.name,t.district_code FROM crop_cycles c JOIN lands l ON l.id=c.land_id JOIN thanas t ON t.code=l.thana_code WHERE l.farmer_id=? AND l.archived=0 ORDER BY l.name,c.sowing_date DESC',[$me['id']])->fetchAll();
$totalArea=query('SELECT COALESCE(SUM(area_sqft)/720,0) FROM lands WHERE farmer_id=?',[$me['id']])->fetchColumn();
$schemes=query("SELECT s.*,d.name AS district_name,a.id AS application_id,a.status AS application_status,a.officer_note,o.name AS reviewing_officer,o.phone AS officer_phone,o.office AS officer_office,sl.snapshot_json FROM schemes s LEFT JOIN districts d ON d.code=s.district_code LEFT JOIN scheme_applications a ON a.scheme_id=s.id AND a.farmer_id=? LEFT JOIN scheme_application_land sl ON sl.application_id=a.id LEFT JOIN officers o ON o.id=a.officer_id WHERE s.status='active' OR a.id IS NOT NULL ORDER BY s.id",[$me['id']])->fetchAll();
?>
<section class="panel scheme-section" id="schemes"><span class="eyebrow">LAND-BASED SUPPORT</span><h2>Scheme applications</h2><p class="muted">Select a land and crop season. Its address, crop, budget and recorded costs are saved for officer review. Approval is a review decision, not a guarantee of supplies.</p><p>Total registered area: <strong><?=e(number_format((float)$totalArea,2))?> katha</strong>. Limits use all your registered lands, including archived records.</p>
<?php if(!$choices):?><p class="error">Add a land and crop season in <a href="land.php">Land & costs</a> before applying.</p><?php endif;?>
<?php if(!$schemes):?><p>No schemes are available yet. Your admin can create schemes.</p><?php endif;?>
<div class="scheme-grid"><?php foreach($schemes as $scheme):$eligible=$totalArea>0 && ($scheme['max_land_katha']===null || (float)$totalArea<(float)$scheme['max_land_katha']);$options=array_filter($choices,fn($c)=>!$scheme['district_code'] || $c['district_code']===$scheme['district_code']);?>
<article class="scheme-card"><div class="card-top"><h3><?=e($scheme['title'])?></h3><?php if($scheme['application_id']):?><span class="badge <?=e($scheme['application_status'])?>"><?=e(ucfirst($scheme['application_status']))?></span><?php endif;?></div>
<?php if($scheme['is_example']):?><small class="scheme-example">Illustrative example · confirm actual availability with the admin</small><?php endif;?>
<p><strong>Support:</strong> <?=e($scheme['benefit'])?></p><p><?=e($scheme['description'])?></p><p class="muted"><?=e($scheme['district_name']?:'All districts')?><?= $scheme['max_land_katha']!==null?' · Total land under '.e($scheme['max_land_katha']).' katha':''?></p>
<?php if($scheme['source_url']):?><p><a href="<?=e($scheme['source_url'])?>" target="_blank" rel="noopener noreferrer">Background source ↗</a></p><?php endif;?>
<?php if($scheme['reviewing_officer']):?><p><strong>Reviewing officer:</strong> <?=e($scheme['reviewing_officer'].' · '.$scheme['officer_phone'].' · '.$scheme['officer_office'])?></p><?php endif;?>
<?php if($scheme['application_id']):?><p><strong>Your application:</strong> <?=e(ucfirst($scheme['application_status']))?><?= $scheme['officer_note']?' · '.e($scheme['officer_note']):''?></p><?php render_land_snapshot($scheme);?>
<?php elseif(!$eligible || !$options):?><p class="muted">Register an eligible land and crop season in the covered district. Your total land area must meet the limit.</p>
<?php else:?><form method="post" class="stack"><?=csrf()?><input type="hidden" name="action" value="apply_scheme"><input type="hidden" name="scheme_id" value="<?=e($scheme['id'])?>"><label>Land and crop season<select name="cycle_id" required><option value="">Choose land / crop</option><?php foreach($options as $option):?><option value="<?=e($option['id'])?>"><?=e($option['name'].' · '.$option['crop'].' · '.$option['season'])?></option><?php endforeach;?></select></label><label>Note for the officer<textarea name="farmer_note" maxlength="500" rows="2"></textarea></label><button>Submit land & costs for review</button></form><?php endif;?></article><?php endforeach;?></div></section>
